CAT = "cfpEstate"; SEG = "EST"
# G. Estate Planning (G.54-G.64). The only indexed figure used is the 2026 gift tax annual exclusion
# ($19,000), named with its year and taken from the IRS gift tax FAQ.
split = 2 * 19000; assert split == 38000
taxable_each = 52000 / 2 - 19000; assert taxable_each == 7000
cp_basis = 2 * 450000; assert cp_basis == 900000
jt_half = 120000 / 2 + 700000 / 2; assert jt_half == 410000
Q = [
("A father's will leaves everything to his son, but his IRA names his daughter as beneficiary. At his death the IRA goes to:",
 "The daughter", ["The son", "The probate estate", "Both children equally"],
 "A beneficiary designation is a contract that passes the account outside the will and outside probate. The will controls only probate assets."),
("Property owned as joint tenants with right of survivorship passes at the first death:",
 "To the surviving owner", ["Under the decedent's will", "Through intestacy rules", "To the decedent's heirs"],
 "Survivorship is automatic, so the decedent's share passes to the surviving joint tenant by law, without probate."),
("A couple in a community property state owns stock worth $900,000 with a basis of $300,000. When the husband dies, the widow's basis in all of it becomes:",
 "$900,000", ["$600,000", "$450,000", "$300,000"],
 "When a spouse dies, both halves of community property generally take a basis equal to fair market value, so the whole $900,000 is stepped up."),
("A married couple owns a stock as joint tenants. It cost $120,000 and is worth $700,000 when the husband dies. The widow's new basis is:",
 "$410,000", ["$700,000", "$120,000", "$350,000"],
 "Only the decedent's half of spousal joint property is stepped up: $60,000 for her half plus $350,000 for his = $410,000."),
("Which document lets an agent manage a client's finances if she becomes incapacitated?",
 "Durable power of attorney", ["Living will", "Health care proxy", "Pour-over will"],
 "A durable power of attorney stays effective after incapacity. A living will and health care proxy deal with medical decisions."),
("A main estate planning reason to fund a revocable living trust during life is to:",
 "Avoid probate on its assets", ["Remove assets from the estate", "Save income tax each year", "Shield assets from her creditors"],
 "Assets titled in a funded revocable trust pass outside probate. Because the grantor can revoke it, they stay in her taxable estate and reachable by her creditors."),
("Under 2026 rules, a married couple who split gifts can give each grandchild how much without using any exemption?",
 "$38,000", ["$19,000", "$15,000", "$30,000"],
 "The 2026 annual exclusion is $19,000 per donee. With gift splitting each spouse is treated as giving half, so $38,000 per grandchild is excluded."),
("In 2026 a husband gives his nephew $52,000 and his wife consents to split the gift. Each spouse's taxable gift is:",
 "$7,000", ["$33,000", "$14,000", "$0"],
 "Split, each spouse gives $26,000. Less the $19,000 annual exclusion, each has a $7,000 taxable gift, which uses exemption but owes no tax yet."),
("A gift qualifies for the annual exclusion only if it is a gift of:",
 "A present interest", ["A future interest", "Real property", "Cash alone"],
 "The annual exclusion covers present interests, which the donee can use now. Gifts to most trusts are future interests unless the trust gives Crummey withdrawal rights."),
("A widow's executor files a timely estate tax return for her late husband to keep his unused exclusion. This election is called:",
 "Portability", ["Disclaimer", "Gift splitting", "Alternate valuation"],
 "Portability passes the deceased spouse's unused exclusion amount to the survivor, but only if elected on a timely filed Form 706."),
("Property left outright to a spouse who is a U.S. citizen qualifies for a marital deduction of:",
 "An unlimited amount", ["Half the estate", "The annual exclusion", "The exemption amount"],
 "The estate tax marital deduction for property passing to a citizen spouse has no dollar cap. It defers tax to the second death."),
("A decedent's spouse is not a U.S. citizen. To claim the marital deduction, property can pass to her through a:",
 "Qualified domestic trust", ["Bypass trust", "Crummey trust", "Charitable remainder trust"],
 "IRC section 2056(d) denies the marital deduction for a noncitizen spouse unless the property passes into a QDOT, which keeps estate tax collectible."),
("Which trust lets a first spouse qualify assets for the marital deduction while fixing who receives them after the survivor dies?",
 "QTIP trust", ["Bypass trust", "Grantor retained annuity trust", "Irrevocable life insurance trust"],
 "A QTIP gives the spouse all income for life and lets the first spouse name the remainder beneficiaries. The executor elects the marital deduction for it."),
("A client gives a life policy on his own life to his daughter and dies two years later. The death benefit is:",
 "In his gross estate", ["Out of his estate", "Taxed as her income", "Half in his estate"],
 "IRC section 2035 pulls back into the estate a life policy transferred within three years of death."),
("To keep life insurance proceeds out of the insured's estate from the start, the policy should be bought by:",
 "An irrevocable life insurance trust", ["The insured's revocable trust", "The insured personally", "The insured's estate"],
 "If a properly drafted ILIT applies for and owns the policy, the insured holds no incidents of ownership and the three-year rule does not apply."),
("An heir wants an inheritance to pass to her children instead. A qualified disclaimer generally must be made within:",
 "9 months", ["6 months", "12 months", "3 years"],
 "IRC section 2518 requires a written disclaimer within 9 months of the transfer (or of turning 21) before the heir accepts any benefit."),
("If elected, the alternate valuation date for an estate is generally:",
 "6 months after death", ["9 months after death", "The date of probate", "One year after death"],
 "The executor may value the estate six months after death if that lowers both the gross estate and the estate tax due."),
("A parent sells a business to her son for a note that is canceled at her death. This technique is a:",
 "Self-canceling installment note", ["Private annuity", "Grantor retained annuity trust", "Family limited partnership"],
 "A SCIN ends at the seller's death, so the unpaid balance is not in her estate. The note carries a risk premium in price or interest to reflect that."),
("Why might limited partnership units in a family limited partnership be given at less than the value of the assets inside?",
 "Lack of control and marketability", ["IRS rules set a flat 50% discount for all", "Gifts of units are tax-free", "The partnership pays the tax"],
 "Limited partners cannot manage the partnership or sell units easily, which supports valuation discounts on gifts of the units."),
("A parent wants an inheritance for a disabled child without ending his means-tested benefits. The usual tool is a:",
 "Third-party special needs trust", ["Outright gift to the child", "Joint account with the child", "Payable-on-death account"],
 "A trustee with discretion to pay for extra needs keeps the assets from being counted for SSI and Medicaid. Outright ownership could end eligibility."),
]
